UPDATE `aowow_articles`
SET `article` = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(`article`, 'Email your suggestions to [feedback].', 'Send your suggestions through [url=?aboutus#contact]our contact form[/url].'), 'please do so to [feedback].', 'please use [url=?aboutus#contact]our contact form[/url].'), 'please let us know at [feedback].', 'please let us know through [url=?aboutus#contact]our contact form[/url].'), '[url=http://elitistjerks.com/f47/t21302-theorycrafting_think_tank/]Elitist Jerks[/url]', 'Elitist Jerks'), '[url=http://forums.tkasomething.com/showthread.php?t=9542]TKA Something[/url]', 'TKA Something'), '[url=http://druid.wikispaces.com/Healing+Gear+List]The Druid Wiki[/url]', 'The Druid Wiki'), '[url=http://www.emmerald.net/]Emmerald[/url]', 'Emmerald'), '[url=http://www.lootrank.com/wow/templates.asp]Lootrank[/url]', 'Lootrank'), '[url=http://pawnmod.trenchrats.com/index.php]Pawn Mod[/url]', 'Pawn Mod'), '[url=http://www.codeplex.com/Rawr]Rawr[/url]', 'Rawr'), '[url=http://shadowpanther.net/aep.htm]Shadow Panther[/url]', '[url=https://shadowpanther.net/aep.htm]Shadow Panther[/url]')
